def main():
 ap=argparse.ArgumentParser();ap.add_argument('--out',required=True);a=ap.parse_args();out=Path(a.out);out.mkdir(parents=True,exist_ok=True);start=time.monotonic();test=subprocess.run([sys.executable,str(P/'test_quadrature.py')],capture_output=True,text=True);(out/'test_quadrature.log').write_text(test.stdout+test.stderr);assert test.returncode==0
 exact=Fraction(2,7);lumped=Fraction(2,3);assert lumped-exact==Fraction(8,21);assert (lumped-exact)*(1-Fraction(1,64))==Fraction(3,8)
 screen=json.loads((P/'screen_001/result.json').read_text());trans=np.load(P/'screen_001/transfers.npz');temporal=json.loads((P/'temporal_001/result.json').read_text());fields=np.load(P/'temporal_001/temporal_fields.npz');meta=json.loads((P.parent/'cold_full_envelope_data_2026_10_25/fit_002/result.json').read_text())['datasets'];quadratures=[];energies=[];ratios=[]
 for gal in ['Draco','Sextans']:
  parent=P.parent/'cold_fine_late_collapse_2026_10_25'/(gal+'_fine_late');d=json.loads((parent/'result.json').read_text());z=np.load(parent/'field.npz');info=d['units'];data=meta[gal];M=.5*data['supply_Msun'];R=np.sqrt(.00430091*M/(.1*9.3603e-11*3.085677581491367e10));V=np.sqrt(.00430091*M/R);expected=dict(M_Msun=M,R_pc=R,V_kms=V,t_Myr=.97779222168*R/V,eta_code=1500/(R*V),vin_code=10/V,q=data['stellar_mass_Msun']/M);assert d['ne']==8192 and all(np.isclose(info[k],v,rtol=1e-14,atol=0) for k,v in expected.items());aa=np.array(data['tracer_scales_pc'])/R;pb=lambda r:sum(-info['q']/len(aa)/np.sqrt(r*r+b*b) for b in aa);s=Solver(d['ne'],eta=info['eta_code'],vin=info['vin_code'],alpha=d['alpha'],pb=pb);assert np.array_equal(z['r'],s.r) and np.array_equal(z['w'],s.w) and np.array_equal(z['p'],s.p);u=z['u'][-1];phi=s.phi(u);assert np.max(abs(phi-z['phi'][-1]))<1e-12;assert abs(np.vdot(u,u).real/d['initial']['mass']-1)<=1e-8 and abs(s.energy(u,phi)-d['initial']['energy'])/d['initial']['energy_scale']<=1e-4 and s.phase_bad(u)<=.05 and np.sum(abs(u[s.r>.85*s.R])**2)<=1e-4
  screen_record=next(x for x in screen['records'] if x['galaxy']==gal);assert not screen_record['passes_transfer_screen'] and not screen_record['eligible_restart']
  amp=np.r_[0,u/np.sqrt(s.w),0];integrals={str(n):float(cell_mass(s.ne,s.alpha,s.R,amp,n).sum()) for n in [8,16,32]};assert abs(integrals['16']-integrals['32'])<1e-11;oldmass=float(np.vdot(u,u).real);v=trans[gal+'_u'];newmass=float(np.vdot(v,v).real);nodes=np.array([-1.,-1/np.sqrt(5),1/np.sqrt(5),1.]);inv=np.linalg.inv(np.polynomial.legendre.legvander(nodes,3));local=amp[3*np.arange(s.ne)[:,None]+np.arange(4)[None,:]];a3=local@inv[3];Jmid=s.R*s.alpha*np.cosh(s.alpha*(np.arange(s.ne)+.5)/s.ne)/np.sinh(s.alpha);leading=float(np.sum((3/8)*abs(a3)**2*Jmid/(2*s.ne)));quadratures.append(dict(galaxy=gal,parent_guards_verified=True,old_lumped_mass=oldmass,nested_lumped_mass=newmass,Gauss_integrals=integrals,Gauss16_32_difference=abs(integrals['16']-integrals['32']),old_minus_reference=oldmass-integrals['32'],nested_minus_reference=newmass-integrals['32'],old_minus_nested=oldmass-newmass,constant_J_leading_old_minus_nested=leading,mapped_J_correction=(oldmass-newmass)-leading,screen_remains_failed=not screen_record['passes_transfer_screen'],scope='same cubic interpolant integral only; no evolved-field correction or accepted transfer'))
  ref=data['observed_rhalf_pc']/R
  for rec in [x for x in temporal['rows'] if x['galaxy']==gal]:
   a0=fields[gal+'_'+str(rec['h'])];assert a0.shape==u.shape and np.all(np.isfinite(a0));pp=s.phi(a0);E=s.energy(a0,pp);Mend=float(np.vdot(a0,a0).real);refmass=float(np.sum(abs(a0[s.r<ref])**2));err=abs(E-d['initial']['energy'])/d['initial']['energy_scale'];assert err<=rec['maxima']['energy']+1e-10 and abs(Mend/d['initial']['mass']-1)<=rec['maxima']['mass']+1e-12 and abs(refmass-rec['final_reference_mass_code'])<1e-12;energies.append(dict(galaxy=gal,h=rec['h'],status=rec['status'],attained_deltaT=rec['attained_deltaT'],final_energy=E,local_energy_change_over_original_scale=float((E-s.energy(u,phi))/d['initial']['energy_scale']),final_energy_residual_over_original_scale=err,final_mass=Mend,final_reference_mass_Msun=refmass*M,reference_mass_change_from_parent_Msun=(refmass-np.sum(abs(u[s.r<ref])**2))*M))
  pp=[x for x in temporal['pairs'] if x['galaxy']==gal]
  if len(pp)==2:ratios.append(dict(galaxy=gal,wave_difference_ratio=pp[0]['wave_L2']/pp[1]['wave_L2'],observed_local_wave_order=float(np.log2(pp[0]['wave_L2']/pp[1]['wave_L2'])),CDF_difference_ratio=pp[0]['CDF_sup_difference']/pp[1]['CDF_sup_difference'],scope='finite local fixed-grid temporal ratios, not global/spatial convergence'))
  z.close()
 assert resource.getrusage(resource.RUSAGE_SELF).ru_maxrss<750000000;result=dict(scope='posthoc diagnostic addendum; original producer fields and failed transfer gates unchanged',quadratures=quadratures,temporal_final_energies=energies,temporal_ratios=ratios,exact_constant_J=dict(P3_norm=str(exact),Lobatto_P3_norm=str(lumped),defect=str(lumped-exact),nested_difference='3/8'),tests=3,seconds=time.monotonic()-start,peak_RSS_bytes=resource.getrusage(resource.RUSAGE_SELF).ru_maxrss);(out/'result.json').write_text(json.dumps(result,indent=2));print(json.dumps(dict(tests=3,records=len(quadratures),temporal_states=len(energies),seconds=result['seconds'])))
